Jv1s2_3 = r1*cos(angle2)*cos(angle3)*cos(sq1)*cos(sq3) - r1*cos(sq1)*sin(sq3)*(cos(angle1)*sin(angle3) - cos(angle3)*sin(angle1)*sin(angle2)) - r1*sin(sq1)*(sin(angle1)*sin(angle3) + cos(angle1)*cos(angle3)*sin(angle2));
