Jv1s3_3 = 0;

Jv1s = [Jv1s1_1, Jv1s1_2, Jv1s1_3;Jv1s2_1, Jv1s2_2, Jv1s2_3;Jv1s3_1, Jv1s3_2, Jv1s3_3];

% Jv2 & Jv2s
Jv21_1 = (cos(angle1)*sin(angle3) - cos(angle3)*sin(angle1)*sin(angle2))*(r2*sin(sq1 + sq2)*sin(sq3) + l1*sin(sq1)*sin(sq3)) - (sin(angle1)*sin(angle3) + cos(angle1)*cos(angle3)*sin(angle2))*(r2*cos(sq1 + sq2) + l1*cos(sq1)) - cos(angle2)*cos(angle3)*(r2*sin(sq1 + sq2)*cos(sq3) + l1*cos(sq3)*sin(sq1));
